-- ===================================================================================================
-- Part 2 — hand-written objects
-- ===================================================================================================

-- queue_counter (ADR-008)
ALTER TABLE "queue_counter" ADD CONSTRAINT "queue_counter_values_check" CHECK (last_token >= 0 AND walk_in_count >= 0);

-- queue_entry (Arch 11.15)
ALTER TABLE "queue_entry" ADD CONSTRAINT "queue_entry_token_check" CHECK (token_number >= 1);
ALTER TABLE "queue_entry" ADD CONSTRAINT "queue_entry_recall_check" CHECK (recall_count BETWEEN 0 AND 3);
ALTER TABLE "queue_entry" ADD CONSTRAINT "queue_entry_scheduled_check" CHECK ((source = 'SCHEDULED') = (appointment_id IS NOT NULL));
ALTER TABLE "queue_entry" ADD CONSTRAINT "queue_entry_registered_check" CHECK (status <> 'REGISTERED' OR source = 'QR_WALK_IN');
ALTER TABLE "queue_entry" ADD CONSTRAINT "queue_entry_arrival_check" CHECK (status NOT IN ('WAITING', 'CALLED', 'IN_CONSULTATION', 'COMPLETED', 'NO_SHOW') OR (arrived_at IS NOT NULL AND sort_time IS NOT NULL));
ALTER TABLE "queue_entry" ADD CONSTRAINT "queue_entry_expired_check" CHECK (status <> 'EXPIRED' OR arrived_at IS NULL);
-- FR-QUE-012: a doctor has at most one CALLED or IN_CONSULTATION entry (DOCTOR_BUSY).
CREATE UNIQUE INDEX "queue_entry_doctor_busy" ON "queue_entry" ("doctor_id") WHERE status IN ('CALLED', 'IN_CONSULTATION');

-- ADR-016 layer 3: only SRS 9.3 transitions QT-01..QT-14.
CREATE FUNCTION queue_status_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'REGISTERED'      AND NEW.status IN ('WAITING', 'CANCELLED', 'EXPIRED'))
    OR (OLD.status = 'WAITING'         AND NEW.status IN ('CALLED', 'CANCELLED'))
    OR (OLD.status = 'CALLED'          AND NEW.status IN ('IN_CONSULTATION', 'WAITING', 'NO_SHOW', 'CANCELLED'))
    OR (OLD.status = 'IN_CONSULTATION' AND NEW.status = 'COMPLETED')
  ) THEN
    RAISE EXCEPTION 'invalid queue transition % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER "queue_status_guard" BEFORE UPDATE OF status ON "queue_entry"
  FOR EACH ROW EXECUTE FUNCTION queue_status_guard();

GRANT USAGE ON TYPE queue_source, queue_status TO sc_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "queue_counter", "queue_entry", "clinic_event" TO sc_app;
GRANT USAGE, SELECT ON SEQUENCE "clinic_event_id_seq" TO sc_app;
GRANT ALL ON "queue_counter", "queue_entry", "clinic_event" TO sc_owner;
